@using sv_5a7b200bcc204eba9ea9b2991ff113cc.Services

<div class="message-area">
    <div class="message-area-header">
        <h5># @Channel.Name</h5>
        <span class="channel-desc">@Channel.Description</span>
    </div>

    <div class="message-list" @onscroll="HandleScroll">
        @if (IsLoadingMore)
        {
            <div class="loading-indicator">Loading older messages...</div>
        }

        @foreach (var message in Messages)
        {
            <MessageBubble Message="message"
                           ReplyCount="GetReplyCount(message.Id)"
                           OnOpenThread="() => OnOpenThread.InvokeAsync(message.Id)"
                           OnReact="(emoji) => OnReact.InvokeAsync((message.Id, emoji))" />
        }
    </div>

    <div class="message-input-area">
        <textarea class="message-textarea"
                  @bind="newMessageText"
                  @bind:event="oninput"
                  @onkeydown="HandleKeyDown"
                  placeholder="Message #@Channel.Name"
                  rows="2"></textarea>
        <button class="send-btn" @onclick="SendMessage" disabled="@string.IsNullOrWhiteSpace(newMessageText)">
            Send
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public Channel Channel { get; set; } = default!;
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = new();
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }

    private string newMessageText = string.Empty;

    private int GetReplyCount(int messageId)
    {
        return ThreadReplyCounts.GetValueOrDefault(messageId, 0);
    }

    private async Task HandleScroll(EventArgs e)
    {
        // Scroll-to-top triggers load more (handled via JS interop in production;
        // here we provide the callback for the parent to wire up)
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendMessage();
        }
    }

    private async Task SendMessage()
    {
        if (string.IsNullOrWhiteSpace(newMessageText)) return;
        var text = newMessageText.Trim();
        newMessageText = string.Empty;
        await OnSendMessage.InvokeAsync(text);
    }
}

.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    background-color: #fff;
}

.message-area-header {
    padding: 0.75rem 1.25rem;
    border-bottom: 1px solid #e3e5e8;
    flex-shrink: 0;
}

.message-area-header h5 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #2c2f33;
}

.channel-desc {
    font-size: 0.8rem;
    color: #72767d;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 1rem 0.5rem;
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.loading-indicator {
    text-align: center;
    padding: 0.5rem;
    font-size: 0.8rem;
    color: #72767d;
}

.message-input-area {
    padding: 0.75rem 1rem;
    border-top: 1px solid #e3e5e8;
    display: flex;
    gap: 0.5rem;
    align-items: flex-end;
    flex-shrink: 0;
}

.message-textarea {
    flex: 1;
    resize: none;
    border: 1px solid #e3e5e8;
    border-radius: 8px;
    padding: 0.5rem 0.75rem;
    font-size: 0.9rem;
    font-family: inherit;
    outline: none;
    transition: border-color 0.15s;
}

.message-textarea:focus {
    border-color: #5865f2;
}

.send-btn {
