.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    background-color: #f9fafb;
    border-left: 1px solid #e3e5e8;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #e3e5e8;
    flex-shrink: 0;
}

.thread-header h6 {
    margin: 0;
    font-weight: 700;
    font-size: 1rem;
    color: #2c2f33;
}

.close-btn {
    border: none;
    background: none;
    font-size: 1.1rem;
    cursor: pointer;
    color: #72767d;
    padding: 0.2rem 0.4rem;
    border-radius: 3px;
}

.close-btn:hover {
    background-color: #e3e5e8;
    color: #2c2f33;
}

.thread-root-message {
    padding: 0.75rem 1rem;
    background-color: #eef1f5;
    border-bottom: 1px solid #e3e5e8;
    flex-shrink: 0;
}

.root-author {
    font-weight: 700;
    font-size: 0.85rem;
    color: #2c2f33;
    margin-bottom: 0.2rem;
}

.root-content {
    font-size: 0.85rem;
    color: #4f5660;
    white-space: pre-wrap;
    word-break: break-word;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 0.75rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.thread-reply {
    padding: 0.4rem 0.6rem;
    border-radius: 4px;
}

.thread-reply:hover {
    background-color: #eef1f5;
}

.reply-header {
    display: flex;
    align-items: baseline;
    gap: 0.4rem;
    margin-bottom: 0.15rem;
}

.reply-author {
    font-weight: 600;
    font-size: 0.82rem;
    color: #2c2f33;
}

.reply-time {
    font-size: 0.7rem;
    color: #72767d;
}

.reply-content {
    font-size: 0.85rem;
    color: #2e3338;
    white-space: pre-wrap;
    word-break: break-word;
}

.thread-input-area {
    padding: 0.75rem;
    border-top: 1px solid #e3e5e8;
    display: flex;
    gap: 0.5rem;
    align-items: flex-end;
    flex-shrink: 0;
}

.thread-textarea {
    flex: 1;
    resize: none;
    border: 1px solid #e3e5e8;
    border-radius: 8px;
    padding: 0.4rem 0.6rem;
    font-size: 0.85rem;
    font-family: inherit;
    outline: none;
}

.thread-textarea:focus {
    border-color: #5865f2;
}

.reply-btn {
    background-color: #5865f2;
    color: white;
    border: none;
    border-radius: 6px;
    padding: 0.4rem 1rem;
    font-weight: 600;
    font-size: 0.8rem;
    cursor: pointer;
}

.reply-btn:hover:not(:disabled) {
    background-color: #4752c4;
}

.reply-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

