+        </div>
+    }
+</div>
+
+@code {
+    private List<Channel> channels = [];
+    private List<Message> messages = [];
+    private List<Message> threadMessages = [];
+    private Dictionary<int, int> threadReplyCounts = new();
+
+    private Channel? activeChannel;
+    private int activeChannelId;
+    private Message? threadRootMessage;
+    private bool threadOpen;
+    private bool isLoadingMore;
+
+    private const int PageSize = 30;
+
+    protected override async Task OnInitializedAsync()
+    {
+        channels = await ChatService.GetChannelsAsync();
+        if (channels.Count > 0)
+        {
+            await SelectChannel(channels[0].Id);
+        }
+    }
+
+    private async Task SelectChannel(int channelId)
+    {
+        activeChannelId = channelId;
+        activeChannel = channels.FirstOrDefault(c => c.Id == channelId);
+        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
+        await ChatService.MarkChannelReadAsync(channelId);
+        await BuildThreadReplyCounts();
+        CloseThread();
+        StateHasChanged();
+    }
+
+    private async Task LoadMoreMessages()
+    {
+        if (isLoadingMore || activeChannel is null) return;
+        isLoadingMore = true;
+        StateHasChanged();
+
+        var olderMessages = await ChatService.GetMessagesAsync(activeChannelId, messages.Count, PageSize);
+        if (olderMessages.Count > 0)
+        {
+            messages.InsertRange(0, olderMessages);
+            await BuildThreadReplyCounts();
+        }
+
+        isLoadingMore = false;
+        StateHasChanged();
+    }
+
+    private async Task SendMessage(string content)
+    {
+        if (activeChannel is null) return;
+        var message = await ChatService.SendMessageAsync(activeChannelId, content, null);
+        messages.Add(message);
+        StateHasChanged();
+    }
+
+    private async Task OpenThread(int messageId)
+    {
+        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
+        if (threadRootMessage is null) return;
+
+        threadMessages = await ChatService.GetThreadAsync(messageId);
+        threadOpen = true;
+        StateHasChanged();
+    }
+
+    private void CloseThread()
+    {
+        threadOpen = false;
+        threadRootMessage = null;
+        threadMessages = [];
+    }
+
+    private async Task SendThreadReply(string content)
+    {
+        if (threadRootMessage is null || activeChannel is null) return;
+        var reply = await ChatService.SendMessageAsync(activeChannelId, content, threadRootMessage.Id);
+        threadMessages.Add(reply);
+
+        // Update reply count
+        threadReplyCounts[threadRootMessage.Id] = threadMessages.Count;
+        StateHasChanged();
+    }
+
+    private async Task HandleReaction((int MessageId, string Emoji) args)
+    {
+        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
+        // Refresh messages to show updated reactions
+        if (activeChannel is not null)
+        {
+            messages = await ChatService.GetMessagesAsync(activeChannelId, 0, messages.Count);
+        }
+        StateHasChanged();
+    }
+
+    private async Task BuildThreadReplyCounts()
+    {
+        threadReplyCounts.Clear();
+        // Identify thread starters: messages that have replies pointing to them
+        var rootIds = messages
+            .Where(m => m.ReplyToId is null)
+            .Select(m => m.Id)
+            .ToHashSet();
+
+        foreach (var rootId in rootIds)
+        {
+            var thread = await ChatService.GetThreadAsync(rootId);
+            if (thread.Count > 0)
+            {
+                threadReplyCounts[rootId] = thread.Count;
+            }
+        }
+    }
+}
+

